package br.com.nuvemtv;
import android.os.Looper;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import org.json.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,qualifiers="w960dp-h540dp-land-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class HomeNavigationTest {
 ActivityController<MainActivity> controller;MainActivity a;
 @Before public void open()throws Exception{RuntimeEnvironment.getApplication().getSharedPreferences("vault",0).edit().clear().commit();RuntimeEnvironment.getApplication().getSharedPreferences("settings",0).edit().clear().putString("language","pt-BR").commit();controller=Robolectric.buildActivity(MainActivity.class).setup();a=controller.get();a.signedIn=true;JSONArray ids=new JSONArray();for(int i=0;i<30;i++){String pid=String.format("9%011d",i);ids.put(pid);a.catalog.put(Json.obj("id","game-"+i,"productId",pid,"name","Jogo "+i,"cover","","genres",Json.arr("Ação")));}a.feed=Json.obj("popular",ids,"added",ids,"leaving",ids,"updatedAt",System.currentTimeMillis());a.navigate("home");layout();}
 @After public void close(){controller.pause().stop().destroy();}
 void layout(){Shadows.shadowOf(Looper.getMainLooper()).idle();a.root.measure(View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY));a.root.layout(0,0,1920,1080);Shadows.shadowOf(Looper.getMainLooper()).idle();}
 void key(int code){assertNotNull("Foco antes da tecla: "+a.homeFocus,a.root.findFocus());a.root.findFocus().dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,code));a.root.findFocus().dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,code));layout();}
 @Test public void homeHasOnlyCategoriesAndKeepsFlatLibrarySeparate(){assertNull(a.grid);assertNull(a.searchBox);assertNotNull(LibraryUiTest.find(a.body,"Todos os jogos"));assertEquals(4,a.shelves.size());assertNotNull(LibraryUiTest.find(a.body,"Mais populares em nuvem"));assertNotNull(LibraryUiTest.find(a.body,"Adicionados recentemente"));assertNotNull(LibraryUiTest.find(a.body,"Saindo de cena em breve"));a.navigate("library");assertNotNull(a.grid);assertEquals(30,a.grid.getCount());}
 @Test public void longShelfRecyclesFourCellsAndReturnsFocusAfterDetails()throws Exception{TvShelf shelf=a.shelves.get(0);assertTrue(shelf.cells.size()<=4);shelf.focusAt(0);for(int i=0;i<20;i++)key(KeyEvent.KEYCODE_DPAD_RIGHT);assertEquals(20,shelf.index);assertEquals(30,shelf.items.length());assertTrue(shelf.cells.size()<=4);assertTrue(shelf.cells.get(shelf.index-shelf.first).hasFocus());a.details(shelf.items.getJSONObject(20));a.onBackPressed();layout();assertEquals(20,a.shelves.get(0).index);assertEquals("Jogo 20",a.root.findFocus().getContentDescription().toString());}
 @Test public void verticalNavigationAndGenreTilesWork(){a.shelves.get(0).focusAt(7);key(KeyEvent.KEYCODE_DPAD_DOWN);assertEquals("shelf:added",a.homeFocus);key(KeyEvent.KEYCODE_DPAD_UP);assertEquals("shelf:popular",a.homeFocus);a.query="um filtro antigo";a.shelves.get(3).focusAt(0);a.root.findFocus().performClick();layout();assertEquals("library",a.tab);assertEquals("Ação",a.genre);assertEquals("",a.query);assertEquals(30,a.grid.getCount());}
 @Test public void permissionDenialNeverEnablesMicrophone(){a.settings();Switch mic=a.root.findViewWithTag("setting:microphone");assertNotNull(mic);assertFalse(mic.isChecked());mic.setChecked(true);assertFalse(a.prefs.getBoolean("microphone",false));a.onRequestPermissionsResult(40,new String[]{android.Manifest.permission.RECORD_AUDIO},new int[]{android.content.pm.PackageManager.PERMISSION_DENIED});assertFalse(mic.isChecked());assertFalse(a.prefs.getBoolean("microphone",false));}
 @Test public void rendersHomeAndGenresAtTvResolution()throws Exception{
  String fixture=System.getProperty("bxbox.qa.fixture"),out=System.getProperty("bxbox.qa.dir");if(fixture==null||out==null)return;
  java.nio.file.Path dir=java.nio.file.Paths.get(fixture);a.catalog=new JSONArray(new String(java.nio.file.Files.readAllBytes(dir.resolve("catalog.json")),java.nio.charset.StandardCharsets.UTF_8));a.feed=new JSONObject(new String(java.nio.file.Files.readAllBytes(dir.resolve("feed.json")),java.nio.charset.StandardCharsets.UTF_8));a.recent=Json.arr(a.catalog.getJSONObject(0));
  java.io.File cache=new java.io.File(a.getCacheDir(),"covers-v2");cache.mkdirs();try(java.util.stream.Stream<java.nio.file.Path> files=java.nio.file.Files.list(dir)){for(java.nio.file.Path file:files.filter(p->p.toString().endsWith(".jpg")).collect(java.util.stream.Collectors.toList()))java.nio.file.Files.copy(file,cache.toPath().resolve(file.getFileName()),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}
  a.navigate("home");layout();Thread.sleep(600);layout();a.shelves.get(0).focusAt(0);layout();snapshot(out,"home.png");a.shelves.get(a.shelves.size()-1).focusAt(0);layout();snapshot(out,"genres.png");
 }
 void snapshot(String dir,String name)throws Exception{java.io.File output=new java.io.File(dir);output.mkdirs();android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(1920,1080,android.graphics.Bitmap.Config.ARGB_8888);invalidate(a.root);a.root.getViewTreeObserver().dispatchOnPreDraw();a.root.draw(new android.graphics.Canvas(image));try(java.io.FileOutputStream file=new java.io.FileOutputStream(new java.io.File(output,name))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,file);}image.recycle();}
 void invalidate(View v){v.setLayerType(View.LAYER_TYPE_SOFTWARE,null);v.invalidate();if(v instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)v;for(int i=0;i<group.getChildCount();i++)invalidate(group.getChildAt(i));}}
 @Test public void releasesShelfViewsBeforeStreaming(){assertFalse(a.shelves.isEmpty());a.releaseLibraryViews();assertTrue(a.shelves.isEmpty());assertTrue(a.images.isPaused());assertNull(a.root);}
 @Test public void recentMovesToHomeAndOwnedTabExcludesCatalogGames()throws Exception{
  a.recent=Json.arr(a.catalog.getJSONObject(2));a.feed.put("gamepass",Json.arr(a.catalog.getJSONObject(3).getString("productId")));a.feed.put("own",Json.arr(a.catalog.getJSONObject(4).getString("productId")));a.navigate("home");layout();assertEquals("recent",a.shelves.get(0).key);assertEquals("popular",a.shelves.get(1).key);assertNull(a.navButtons.get("recent"));assertNotNull(a.navButtons.get("friends"));assertNotNull(a.navButtons.get("owned"));assertNull(a.navButtons.get("library"));a.ownedGames=Json.arr(a.catalog.getJSONObject(5));a.navigate("owned");layout();assertEquals(1,a.grid.getCount());assertEquals("game-5",a.adapter.getItem(0).getString("id"));
 }
 @Test public void languageFollowsSystemAndCanBeOverridden(){assertEquals("en-US",I18n.resolve("system",java.util.Locale.ENGLISH));assertEquals("pt-BR",I18n.resolve("system",new java.util.Locale("pt","PT")));assertEquals("es-ES",I18n.resolve("system",new java.util.Locale("es","MX")));assertEquals("pt-BR",I18n.resolve("pt-BR",java.util.Locale.ENGLISH));a.prefs.edit().putString("language","en-US").commit();assertEquals("Voltar",a.text("Voltar",12).getText().toString());assertEquals("Back",a.tr("Voltar"));a.navigate("home");assertNotNull(LibraryUiTest.find(a.root,"Play with friends"));assertNotNull(LibraryUiTest.find(a.root,"My games"));a.settings();assertNotNull(LibraryUiTest.find(a.root,"Language"));assertNotNull(LibraryUiTest.find(a.root,"Enable microphone"));a.prefs.edit().putString("language","es-ES").commit();a.settings();assertNotNull(LibraryUiTest.find(a.root,"Activar micrófono"));}
 @Test public void officialHeroDoesNotUseRecentlyPlayedGame()throws Exception{a.recent=Json.arr(a.catalog.getJSONObject(2));a.feed.put("promotions",Json.arr(Json.obj("productId",a.catalog.getJSONObject(7).getString("productId"),"name","Campaign","subtitle","Official campaign")));a.navigate("home");assertNotNull(LibraryUiTest.find(a.body,"Jogo 7"));assertNotNull(LibraryUiTest.find(a.body,"DESTAQUES DO XBOX"));assertNull(LibraryUiTest.find(a.body,"EM DESTAQUE NA SUA BIBLIOTECA"));}
}
